from __future__ import annotations

from hc_common import make_build

MATERIALS = "Papel, lápiz y goma. Tablas, cartolas, avisos y gráficos de ejemplo escritos o dibujados en papel; no se usa dinero real, ni datos personales, ni calculadora ni internet. Todo se resuelve con lo escrito en la ficha. Las cifras son inventadas y no corresponden a tasas, comisiones, precios ni indicadores reales; este cuaderno no entrega asesoría financiera ni recomienda productos."
build = make_build(MATERIALS)

O5 = "EPJA-EFIN-NM1y2-OAD-05"
O6 = "EPJA-EFIN-NM1y2-OAD-06"
O7 = "EPJA-EFIN-NM1y2-OAD-07"
O8 = "EPJA-EFIN-NM1y2-OAD-08"
PRIOR = ["Ya he guardado dinero para algo o he visto a otras personas hacerlo.", "Sé calcular sumas, restas, multiplicaciones y divisiones con pesos."]


def K(oa, n, F, use, explain, vocab, worked, mistakes, T, ctx, sc, op, rf, ex_):
    op = list(op)
    if isinstance(op[4], str):
        op[4] = [e.strip() for e in op[4].split(";")]
    build(oa, n, F, use=use, prior=PRIOR, explain=explain, vocab=vocab, worked=worked, mistakes=mistakes, T=T, ctx=ctx, sc=sc, op=op, reinforce=rf, extend=ex_)


